def render_card(badge_class, badge_text, q_title, q_sub, q_options, ans_head, ans_body, rule_title, rule_content, ex_ja="", ex_ko=""):
    opt_html = "".join(f'<div class="vt-opt">{opt}</div>' for opt in q_options) if q_options else ""
    front = (
        f"{CSS_BLOCK}"
        f'<div class="vt-wrap vt-center">'
        f'<span class="vt-badge {badge_class}">{badge_text}</span>'
        f'<div class="vt-title">{q_title}</div>'
        f'<div class="vt-sub">{q_sub}</div>'
        f'{opt_html}'
        f'</div>'
    )
    ex_html = ""
    if ex_ja:
        ex_html = f'<div class="vt-ex-ja"><span class="vt-tag">예문:</span> {ex_ja}</div><div class="vt-ex-ko">{ex_ko}</div>'
    back = (
        f"{CSS_BLOCK}"
        f'<div class="vt-wrap">'
        f'<div class="vt-ans-head">{ans_head}</div>'
        f'<div class="vt-sec">'
        f'<div class="vt-meaning">{ans_body}</div>'
        f'{ex_html}'
        f'</div>'
        f'<div class="vt-rule-box">'
        f'<div class="vt-rule-title">{rule_title}</div>'
        f'<div class="vt-rule-content">{rule_content}</div>'
        f'</div>'
        f'</div>'
    )
    return front, back

