def mcp(method: str, params: dict, request_id: int) -> dict:
    data = json.dumps({"jsonrpc": "2.0", "id": request_id, "method": method, "params": params}, ensure_ascii=False).encode("utf-8")
    req = urllib.request.Request(
        ENDPOINT,
        data=data,
        headers={"Content-Type": "application/json", "Accept": "application/json, text/event-stream"},
        method="POST",
    )
    with urllib.request.urlopen(req, timeout=30) as response:
        body = response.read().decode("utf-8")
    payload = json.loads(next(line[6:] for line in body.splitlines() if line.startswith("data: ")))
    if "error" in payload:
        raise RuntimeError(payload["error"])
    return payload["result"]

def tool(name: str, arguments: dict, request_id: int) -> dict:
    result = mcp("tools/call", {"name": name, "arguments": arguments}, request_id)
    if result.get("isError"):
        raise RuntimeError(result)
    if "structuredContent" in result:
        return result["structuredContent"]
    return json.loads(next(x["text"] for x in result["content"] if x["type"] == "text"))

def process_deck(deck_name: str, cards_data: list, base_req_id: int):
    print(f"\n==========================================")
    print(f"Processing '{deck_name}' ({len(cards_data)} cards)...")
    clean_name = deck_name.split("::")[-1].replace(" ", "_").replace("・", "_")
    tsv_filename = f"{clean_name}_{len(cards_data)}cards.txt"
    tsv_path = OUTPUT_DIR / tsv_filename

    tsv_rows = [
        "#separator:Tab",
        "#html:true",
        f"#deck:{deck_name}",
        "#tags column:3",
        "#columns:Front\tBack\tTags"
    ]

    notes_to_add = []
    tag_name = deck_name.split("::")[-1].split(" ")[-1]
    for c in cards_data:
        b_class, b_text, q_title, q_sub, q_opt, a_head, a_body, r_title, r_content, ex_ja, ex_ko = c
        f, b = render_card(b_class, b_text, q_title, q_sub, q_opt, a_head, a_body, r_title, r_content, ex_ja, ex_ko)
        f_clean = f.replace("\t", " ").replace("\n", "")
        b_clean = b.replace("\t", " ").replace("\n", "")
        tsv_rows.append(f"{f_clean}\t{b_clean}\tJLPT_N2 {tag_name}")
        notes_to_add.append({
            "fields": {"Front": f_clean, "Back": b_clean},
            "tags": ["JLPT_N2", tag_name],
        })

    tsv_path.write_text("\n".join(tsv_rows) + "\n", encoding="utf-8")
    print(f"Saved clean TSV: {tsv_path.name}")

    # Create deck in Anki
    tool("create_deck", {"deck_name": deck_name}, base_req_id)
    base_req_id += 1

    # Check existing count
    exist = tool("find_notes", {"query": f'deck:"{deck_name}"', "limit": 200}, base_req_id)
    base_req_id += 1
    existing_count = exist.get("count", 0)
    print(f"Existing count in deck: {existing_count}")

    if existing_count < len(cards_data):
        chunk_size = 50
        for i in range(0, len(notes_to_add), chunk_size):
            chunk = notes_to_add[i:i+chunk_size]
            res = tool("add_notes", {
                "deck_name": deck_name,
                "model_name": "Basic",
                "notes": chunk,
                "tags": ["JLPT_N2", tag_name],
                "allow_duplicate": False,
            }, base_req_id)
            base_req_id += 1
            print(f"Added batch {i//chunk_size + 1}: {len(chunk)} cards")

    # Verify
    verify = tool("find_notes", {"query": f'deck:"{deck_name}"', "limit": 200}, base_req_id)
    base_req_id += 1
    print(f"Verified count: {verify.get('count', 0)} / {len(cards_data)}")
    assert verify.get("count", 0) == len(cards_data)
    return base_req_id

def main():
    mcp("initialize", {"protocolVersion": "2025-03-26", "capabilities": {}, "clientInfo": {"name": "decks-builder-1", "version": "1.0"}}, 1)
    req_id = 10
    req_id = process_deck(DECK_04_NAME, CARDS_04, req_id)
    req_id = process_deck(DECK_05_NAME, CARDS_05, req_id)
    req_id = process_deck(DECK_06_NAME, CARDS_06, req_id)
    req_id = process_deck(DECK_07_NAME, CARDS_07, req_id)
    print("\n[SUCCESS] Decks 04, 05, 06, 07 successfully built and verified!")

if __name__ == "__main__":
    main()
